pid_t pid = fork();
int status;

if (pid == 0) {
    // Child: Terminates immediately (becomes ZOMBIE pending wait)
    _exit(42);
}

if (pid > 0) {
    // Parent: Use wait() to retrieve status
    // and fully reap the terminated child process.
    pid_t reaped_pid = wait(&status);

    // WIFEXITED(status) check determines exit type
}
